INSERT INTO fln_lessons (lesson_code, title_hindi, title_santhali, grade, domain, duration_minutes, steps_json, worksheet_generated) VALUES 
('LES_G1_NUM_01', 'गिनती सीखें 1 से 5', 'ᱮᱞ ᱪᱮᱫᱚᱜ ᱑ ᱠᱷᱚᱱ ᱕', 1, 'numeracy', 20, '[{"step": 1, "type": "intro", "text_hi": "नमस्ते बच्चों, आज हम 1 से 5 तक गिनती सीखेंगे।", "text_sat": "ᱡᱚᱦᱟᱨ ᱜᱤᱫᱽᱨᱟᱹ, ᱛᱮᱦᱮᱧ ᱟᱵᱚ ᱑ ᱠᱷᱚᱱ ᱕ ᱦᱟᱹᱵᱤᱡ ᱮᱞ ᱵᱚᱱ ᱪᱮᱫᱚᱜᱼᱟ᱾"}, {"step": 2, "type": "listen_repeat", "phrase_code": "NUM_001"}, {"step": 3, "type": "listen_repeat", "phrase_code": "NUM_002"}, {"step": 4, "type": "activity", "instruction": "उंगलियों से दिखाओ और बोलो"}, {"step": 5, "type": "quiz", "question": "दो के बाद क्या आता है?", "answer": "तीन / ᱯᱚᱱ"}]', 1),
('LES_G1_OL_01', 'कक्षा के बुनियादी निर्देश', 'ᱠᱞᱟᱥ ᱨᱮᱱᱟᱜ ᱢᱩᱬᱩᱛ ᱱᱤᱨᱫᱮᱥ', 1, 'oral_language', 15, '[{"step": 1, "type": "intro", "text_hi": "कक्षा में ध्यान से सुनना और बैठना।", "text_sat": "ᱠᱞᱟᱥ ᱨᱮ ᱫᱷᱮᱭᱟᱱ ᱛᱮ ᱟᱧᱡᱚᱢ ᱟᱨ ᱫᱩᱲᱩᱵ᱾"}, {"step": 2, "type": "action", "phrase_code": "CLS_001"}, {"step": 3, "type": "action", "phrase_code": "CLS_004"}, {"step": 4, "type": "praise", "phrase_code": "CLS_008"}]', 1),
('LES_G1_PHN_01', 'ध्वनि पहचान और अक्षर ज्ञान', 'ᱟᱲᱟᱝ ᱪᱤᱱᱦᱟᱹᱣ ᱟᱨ ᱪᱤᱠᱤ ᱜᱮᱭᱟᱱ', 1, 'phonological', 25, '[{"step": 1, "type": "intro", "text_hi": "शब्द की पहली आवाज़ को पहचानना।", "text_sat": "ᱥᱟᱵᱟᱫ ᱨᱮᱱᱟᱜ ᱯᱩᱭᱞᱩ ᱟᱲᱟᱝ ᱪᱤᱱᱦᱟᱹᱣ᱾"}, {"step": 2, "type": "practice", "phrase_code": "PHN_001"}, {"step": 3, "type": "practice", "phrase_code": "PHN_003"}]', 0);
